using SoulPilates.Core.Entities;

namespace SoulPilates.Services;

/// <summary>
/// Pure functions over <see cref="Partner"/> + <see cref="InvoiceLine"/> that
/// resolve referee commission rates and amounts. Lives outside the
/// <see cref="InvoiceService"/> so it can be unit-tested without a Mongo
/// fixture (mirrors <c>PayrollService.ResolvePrivateCommissionRate</c>).
/// </summary>
public static class RefereeCommissionCalculator
{
    /// <summary>
    /// Resolves the partner's commission rate for a single invoice line based
    /// on the line's quantity. Picks the **highest** matching rung where
    /// <c>MinPackagesQty ≤ quantity</c>; returns <c>0m</c> when no rung matches
    /// (quantity below the lowest tier, or partner has no tiers configured).
    /// </summary>
    public static decimal ResolveRate(Partner partner, int quantity)
    {
        if (partner.CommissionTiers == null || partner.CommissionTiers.Count == 0)
            return 0m;

        // Highest MinPackagesQty wins among the tiers that qualify.
        decimal? best = null;
        var bestMin = -1;
        foreach (var tier in partner.CommissionTiers)
        {
            if (tier.MinPackagesQty <= quantity && tier.MinPackagesQty > bestMin)
            {
                best = tier.CommissionPercentage;
                bestMin = tier.MinPackagesQty;
            }
        }
        return best ?? 0m;
    }

    /// <summary>
    /// Returns true if the given product type participates in this partner's
    /// referee commission. Case-insensitive, whitespace-tolerant — admin-form
    /// input is forgiving, but storage is canonicalised at write time.
    /// </summary>
    public static bool IsEligible(Partner partner, string? productType)
    {
        if (string.IsNullOrWhiteSpace(productType)) return false;
        if (partner.EligibleProductTypes == null || partner.EligibleProductTypes.Count == 0)
            return false;
        var canonical = productType.Trim();
        foreach (var t in partner.EligibleProductTypes)
        {
            if (string.IsNullOrWhiteSpace(t)) continue;
            if (string.Equals(t.Trim(), canonical, StringComparison.OrdinalIgnoreCase))
                return true;
        }
        return false;
    }

    /// <summary>
    /// Sums commission across all eligible lines on an invoice. Each line's
    /// commission = <c>line.LineTotal × ResolveRate(partner, line.Quantity)</c>.
    /// Lines whose product type isn't eligible (or whose product can't be
    /// resolved) contribute zero.
    /// </summary>
    /// <param name="lineTypes">Map of <c>ProductId → product Type</c>. Lines whose product is missing from the map are skipped.</param>
    public static decimal ComputeInvoiceCommission(
        Partner partner,
        IEnumerable<InvoiceLine> lines,
        IReadOnlyDictionary<string, string?> lineTypes)
    {
        decimal total = 0m;
        foreach (var line in lines)
        {
            if (line.ProductId is null) continue;
            if (!lineTypes.TryGetValue(line.ProductId, out var type)) continue;
            if (!IsEligible(partner, type)) continue;
            var rate = ResolveRate(partner, line.Quantity);
            if (rate <= 0m) continue;
            total += line.LineTotal * rate;
        }
        return total;
    }

    /// <summary>
    /// Same calculation as <see cref="ComputeInvoiceCommission"/> but returns a
    /// per-line breakdown alongside the total. The breakdown is used by
    /// <see cref="RefereePayout.LineBreakdown"/> so the partner statement can
    /// be rendered without re-computing rates (or risking drift if the
    /// underlying tier ladder is later edited).
    /// </summary>
    /// <param name="productNames">Optional map of <c>ProductId → display name</c>;
    /// missing entries fall back to the product id as a stable identifier.</param>
    public static (decimal Total, List<RefereePayoutLine> Breakdown) ComputeInvoiceCommissionWithBreakdown(
        Partner partner,
        IEnumerable<InvoiceLine> lines,
        IReadOnlyDictionary<string, string?> lineTypes,
        IReadOnlyDictionary<string, string>? productNames = null)
    {
        decimal total = 0m;
        var breakdown = new List<RefereePayoutLine>();
        foreach (var line in lines)
        {
            if (line.ProductId is null) continue;
            if (!lineTypes.TryGetValue(line.ProductId, out var type)) continue;
            if (!IsEligible(partner, type)) continue;
            var rate = ResolveRate(partner, line.Quantity);
            if (rate <= 0m) continue;

            var commission = line.LineTotal * rate;
            total += commission;
            breakdown.Add(new RefereePayoutLine
            {
                ProductId = line.ProductId,
                ProductDescriptionSnapshot = productNames is not null
                    && productNames.TryGetValue(line.ProductId, out var name)
                        ? name
                        : string.Empty,
                ProductTypeSnapshot = line.ProductTypeSnapshot ?? type,
                Quantity = line.Quantity,
                LineTotal = line.LineTotal,
                RateApplied = rate,
                Commission = commission,
            });
        }
        return (total, breakdown);
    }
}

using SoulPilates.Core.Entities;

namespace SoulPilates.Core.Interfaces;

/// <summary>
/// Calculates payroll for instructors based on completed sessions and the
/// commission ladder stored on each <see cref="Staff"/> row.
///
/// <para>
/// The legacy <c>InstructorContract</c> collection was retired in P2-S09. The
/// payroll service now reads <c>CommissionModel</c>, <c>Tiers</c>,
/// <c>GroupFlatRatePerClass</c>, <c>GroupRatePerHead</c>,
/// <c>HasTieredPrivateCommission</c>, <c>FlatPrivateCommissionPct</c>, and
/// <c>BaseSalary</c> directly from the staff record. This collapses the
/// dual-source confusion that made bonus / reimbursement work harder than
/// it needed to be.
/// </para>
/// </summary>
public interface IPayrollService
{
    /// <summary>
    /// Computes per-instructor payroll for the given period. Persists a
    /// <see cref="PayrollRun"/> row for audit and re-derives results idempotently.
    /// </summary>
    Task<PayrollRun> CalculatePayrollAsync(DateTime start, DateTime end);

    /// <summary>
    /// P3-S10 — live per-instructor recalc for the self-service portal.
    /// Same aggregation rules as <see cref="CalculatePayrollAsync"/> but
    /// scoped to a single instructor and **does NOT persist a
    /// <see cref="PayrollRun"/> row**. Every instructor dashboard refresh
    /// would otherwise mint a new audit row, which would muddy the
    /// monthly admin payroll history the studio owner actually cares
    /// about.
    /// </summary>
    /// <returns>
    /// Null if no <see cref="Staff"/> row exists for <paramref name="staffId"/>,
    /// or if the instructor has no completed sessions in the window —
    /// either way the controller surfaces an empty earnings view rather
    /// than a 500.
    /// </returns>
    Task<InstructorPayrollResult?> CalculateForInstructorAsync(string staffId, DateTime start, DateTime end);

    /// <summary>
    /// Sum of all instructors' earned commissions (group + private class
    /// earnings, excluding base salary) for the window. Non-persisting — used
    /// by the dashboard Business Summary to fold commissions into profit.
    /// Reuses the same aggregation as <see cref="CalculatePayrollAsync"/>.
    /// </summary>
    Task<decimal> CalculateTotalCommissionsAsync(DateTime start, DateTime end);
}
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(Roles = "Admin,Accountant")]
public class PayrollController : ControllerBase
{
    private readonly IPayrollService _payrollService;

    public PayrollController(IPayrollService payrollService)
    {
        _payrollService = payrollService;
    }

    /// <summary>
    /// Runs payroll for the given month/year. Commission tiers are read from the
    /// <c>Staff</c> entity now (P2-S09); contract CRUD endpoints have been removed —
    /// edit tiers via the staff form on the admin UI instead.
    /// </summary>
    [HttpPost("run")]
    public async Task<IActionResult> RunPayroll([FromQuery] int month, [FromQuery] int year)
    {
        var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
        var end = start.AddMonths(1).AddTicks(-1);
        var run = await _payrollService.CalculatePayrollAsync(start, end);
        return Ok(run.Results);
    }
}

1	using MongoDB.Driver;
2	using SoulPilates.Core.Entities;
3	using SoulPilates.Core.Interfaces;
4	using SoulPilates.Infrastructure.Data;
5	using System.Linq;
6	using System.Collections.Generic;
7	
8	namespace SoulPilates.Services;
9	
10	/// <summary>
11	/// P2-S09 rewrite: payroll is computed exclusively from <see cref="Staff"/> rows,
12	/// resolved via the immutable <see cref="StaffRateRevision"/> ledger as of the
13	/// period end-date. The live <see cref="Staff"/> document remains for non-rate
14	/// metadata (photo, bio, contact) but is never read for rate math.
15	///
16	/// <para>
17	/// Algorithm per instructor (matches the legacy spreadsheet):
18	/// <list type="number">
19	///   <item>Pull all <c>COMPLETED</c> calendar sessions for the period.</item>
20	///   <item>Group by instructor; skip instructors without a staff row.</item>
21	///   <item>Resolve the rate revision that was in force at <c>periodEnd</c>
22	///   via <see cref="IStaffRateRevisionService.ResolveAsOfAsync"/>. This is the
23	///   sole source of truth for the rate sheet — re-running an old month after
24	///   a rate edit therefore reproduces the original rates.</item>
25	///   <item>For each <b>group</b> session: add <c>GroupFlatRatePerClass</c> + <c>GroupRatePerHead × Bookings</c>.</item>
26	///   <item>For each <b>private</b> session: accumulate the fractional package value drawn down by attendees.</item>
27	///   <item>Resolve the private commission rate via tier lookup (or flat fallback) and apply.</item>
28	///   <item>Add <c>BaseSalary</c> for the period to the total.</item>
29	/// </list>
30	/// </para>
31	///
32	/// <para>
33	/// <b>Idempotency.</b> Each call to <see cref="CalculatePayrollAsync"/> upserts
34	/// a single row keyed on <c>(PeriodStart, PeriodEnd)</c>. A unique index in the
35	/// constructor enforces this at the DB level so two parallel admin clicks can
36	/// never produce duplicates that <c>AccountingService</c> would then sum.
37	/// </para>
38	///
39	/// <para>
40	/// Tier resolution is a strict <c>[Min, Max]</c> match against the <em>private class count</em>.
41	/// Empty <c>Tiers</c> falls back to <c>FlatPrivateCommissionPct</c>;
42	/// when <c>HasTieredPrivateCommission</c> is false the flat rate is used unconditionally.
43	/// </para>
44	/// </summary>
45	public class PayrollService : IPayrollService
46	{
47	    private readonly IMongoCollection<Staff> _staff;
48	    private readonly IMongoCollection<CalendarSession> _sessions;
49	    private readonly IMongoCollection<Attendance> _attendances;
50	    private readonly IMongoCollection<ClientPackage> _clientPackages;
51	    private readonly IMongoCollection<PayrollRun> _payrollRuns;
52	    private readonly IMongoCollection<MonthlyCommissionOverride> _commissionOverrides;
53	    private readonly IMongoCollection<Invoice> _invoices;
54	    private readonly IStaffRateRevisionService _revisions;
55	
56	    public PayrollService(MongoDbContext dbContext, IStaffRateRevisionService revisions)
57	    {
58	        _staff = dbContext.GetCollection<Staff>("Staff");
59	        _sessions = dbContext.GetCollection<CalendarSession>("CalendarSessions");
60	        _attendances = dbContext.GetCollection<Attendance>("Attendances");
61	        _clientPackages = dbContext.GetCollection<ClientPackage>("ClientPackages");
62	        _payrollRuns = dbContext.GetCollection<PayrollRun>("PayrollRuns");
63	        _commissionOverrides = dbContext.GetCollection<MonthlyCommissionOverride>("MonthlyCommissionOverrides");
64	        _invoices = dbContext.GetCollection<Invoice>("Invoices");
65	        _revisions = revisions;
66	
67	        // Unique compound index on (PeriodStart, PeriodEnd). Combined with the
68	        // upsert-by-period logic in CalculatePayrollAsync, this is what
69	        // prevents two concurrent admin clicks from producing two PayrollRun
70	        // rows that AccountingService would then double-count.
71	        //
72	        // Pre-existing duplicates would prevent index creation — if that ever
73	        // happens in prod, the operator runs the cleanup migration in
74	        // SoulPilates.Migration first. For a fresh deploy this is a no-op.
75	        var keys = Builders<PayrollRun>.IndexKeys
76	            .Ascending(p => p.PeriodStart)
77	            .Ascending(p => p.PeriodEnd);
78	        _payrollRuns.Indexes.CreateOne(new CreateIndexModel<PayrollRun>(keys,
79	            new CreateIndexOptions { Unique = true, Name = "ux_period" }));
80	    }
81	
82	    public async Task<PayrollRun> CalculatePayrollAsync(DateTime start, DateTime end)
83	    {
84	        // Look up any prior row so we can upsert by (PeriodStart, PeriodEnd)
85	        // and preserve the original CreatedAt across recomputes.
86	        var existing = await _payrollRuns
87	            .Find(p => p.PeriodStart == start && p.PeriodEnd == end)
88	            .FirstOrDefaultAsync();
89	
90	        var run = new PayrollRun
91	        {
92	            Id = existing?.Id,
93	            PeriodStart = start,
94	            PeriodEnd = end,
95	            RunDate = DateTime.UtcNow,
96	            CreatedAt = existing?.CreatedAt ?? DateTime.UtcNow,
97	            UpdatedAt = DateTime.UtcNow,
98	        };
99	
100	        // Only include COMPLETED sessions for payroll calculations.
101	        // The SessionCompletionBackgroundService auto-transitions past-due
102	        // SCHEDULED sessions to COMPLETED (had attendees) or NO_SHOW (empty).
103	        // We pay commissions only for COMPLETED sessions — classes that actually
104	        // happened with at least one arrived attendee.
105	        var sessions = await _sessions
106	            .Find(s => s.StartTime >= start && s.StartTime <= end
107	                    && s.Status == "COMPLETED"
108	                    && s.Origin != "BLOCK")
109	            .ToListAsync();
110	
111	        // Group by instructor up-front so we make at most one Staff lookup per person.
112	        foreach (var group in sessions.GroupBy(s => s.InstructorId))
113	        {
114	            var instructorId = group.Key;
115	            if (string.IsNullOrEmpty(instructorId)) continue;
116	
117	            var staff = await _staff.Find(s => s.Id == instructorId).FirstOrDefaultAsync();
118	            if (staff is null) continue;
119	
120	            // Not yet employed this period — no pay.
121	            if (staff.EmploymentStartDate.HasValue && end < staff.EmploymentStartDate.Value) continue;
122	
123	            // Resolve the in-force rate revision for the period END. Using End
124	            // (not Start) matches what a payroll clerk expects — "pay people
125	            // under whatever rate was in effect when the month closed". The
126	            // revision service lazily bootstraps a baseline if there is no
127	            // revision yet (legacy staff rows), so the result is never null
128	            // for an existing staff member.
129	            var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);
130	
131	            // Monthly commission override takes precedence over the revision.
132	            revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);
133	
134	            var result = await AggregateInstructorAsync(staff, revision, group.ToList());
135	            run.Results.Add(result);
136	        }
137	
138	        // ── Revenue-split commission pass ───────────────────────────────
139	        // Some staff (e.g. an owner-operator) earn a % of the studio's TOTAL
140	        // monthly revenue rather than per-class commission. The rate can be
141	        // tiered on that revenue (e.g. 4% under 100M, 5% at/over). These people
142	        // may not teach at all, so they won't appear in the session loop above —
143	        // process them here from the month's paid revenue.
144	        var revenueSplitStaff = await _staff
145	            .Find(s => s.CommissionModel == "REVENUE_SPLIT")
146	            .ToListAsync();
147	        if (revenueSplitStaff.Count > 0)
148	        {
149	            // Commission is on studio revenue only — the "VAT (online only)" fee
150	            // is a pass-through surcharge, so exclude OnlineFeeAmount from the base.
151	            var monthlyRevenue = (await _invoices
152	                .Find(i => i.IssueDate >= start && i.IssueDate <= end && i.Status == "PAID")
153	                .ToListAsync()).Sum(i => i.TotalNet - i.OnlineFeeAmount);
154	
155	            foreach (var staff in revenueSplitStaff)
156	            {
157	                // Not yet employed this period — no commission.
158	                if (staff.EmploymentStartDate.HasValue && end < staff.EmploymentStartDate.Value) continue;
159	
160	                decimal pct;
161	                if (staff.RevenueCommissionTiers is { Count: > 0 } rtiers)
162	                {
163	                    var rung = rtiers
164	                        .Where(t => monthlyRevenue >= t.MinRevenue
165	                                 && (t.MaxRevenue == null || monthlyRevenue < t.MaxRevenue.Value))
166	                        .OrderByDescending(t => t.MinRevenue)
167	                        .FirstOrDefault()
168	                        ?? rtiers.OrderByDescending(t => t.MinRevenue).First();
169	                    pct = NormalizeCommissionPct(rung.Percentage);
170	                }
171	                else
172	                {
173	                    pct = NormalizeCommissionPct(staff.BaseRate);
174	                }
175	
176	                var commission = monthlyRevenue * pct;
177	
178	                var existingResult = run.Results.FirstOrDefault(r => r.InstructorId == staff.Id);
179	                if (existingResult != null)
180	                {
181	                    existingResult.RevenueCommissionEarnings += commission;
182	                    existingResult.TotalPay += commission;
183	                }
184	                else
185	                {
186	                    // Create the result even when commission is 0 — the owner
187	                    // still draws their base salary this month.
188	                    var rev = await _revisions.ResolveAsOfAsync(staff.Id!, end);
189	                    rev = await ApplyCommissionOverrideAsync(staff.Id!, end, rev);
190	                    var r = await AggregateInstructorAsync(staff, rev, new List<CalendarSession>());
191	                    r.RevenueCommissionEarnings = commission;
192	                    r.TotalPay += commission;
193	                    if (r.TotalPay != 0m) run.Results.Add(r);
194	                }
195	            }
196	        }
197	
198	        run.TotalPayroll = run.Results.Sum(r => r.TotalPay);
199	
200	        if (existing is null)
201	        {
202	            await _payrollRuns.InsertOneAsync(run);
203	        }
204	        else
205	        {
206	            await _payrollRuns.ReplaceOneAsync(p => p.Id == existing.Id, run);
207	        }
208	
209	        return run;
210	    }
211	
212	    /// <summary>
213	    /// P3-S10 — live per-instructor recalc for the instructor self-service portal.
214	    /// Reuses the same <see cref="AggregateInstructorAsync"/> helper as the admin
215	    /// payroll path so the two surfaces never drift. **Deliberately does NOT
216	    /// persist a <see cref="PayrollRun"/> row** — the instructor portal would
217	    /// otherwise pollute the audit history on every dashboard refresh.
218	    ///
219	    /// <para>
220	    /// Reads rates from the in-force revision as-of <paramref name="end"/> so
221	    /// the portal's tier-progress meter matches what the admin payroll path
222	    /// would compute for the same window — including for historical months.
223	    /// </para>
224	    /// </summary>
225	    public async Task<InstructorPayrollResult?> CalculateForInstructorAsync(
226	        string staffId, DateTime start, DateTime end)
227	    {
228	        if (string.IsNullOrWhiteSpace(staffId)) return null;
229	
230	        var staff = await _staff.Find(s => s.Id == staffId).FirstOrDefaultAsync();
231	        if (staff is null) return null;
232	
233	        var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);
234	
235	        // Monthly commission override takes precedence over the revision.
236	        revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);
237	
238	        // Pull only this instructor's COMPLETED sessions — must mirror
239	        // the admin payroll path exactly (Status == "COMPLETED") so the
240	        // instructor portal never shows a different number from the
241	        // admin washout. SCHEDULED/NO_SHOW sessions must be excluded;
242	        // they haven't happened yet (or were empty) and should not
243	        // contribute to the earnings total.
244	        var sessions = await _sessions
245	            .Find(s => s.InstructorId == staffId
246	                    && s.StartTime >= start
247	                    && s.StartTime <= end
248	                    && s.Status == "COMPLETED"
249	                    && s.Origin != "BLOCK")
250	            .ToListAsync();
251	
252	        // Always return a result (even with zero sessions) so the portal
253	        // can show "0 classes · $0 earned this month" rather than a 404.
254	        // Base salary still applies even when no classes have been taught.
255	        return await AggregateInstructorAsync(staff, revision, sessions);
256	    }
257	
258	    /// <summary>
259	    /// Private helper used by both the admin payroll path and the
260	    /// per-instructor portal path. Encapsulates the exact aggregation
261	    /// rules so the two surfaces cannot drift.
262	    ///
263	    /// <para>
264	    /// The <paramref name="rates"/> argument is the in-force
265	    /// <see cref="StaffRateRevision"/>. When it's null (legacy callers or
266	    /// a deleted staff member), we fall back to the live <c>Staff</c> values
267	    /// — this is the only place the live values are still trusted, and it
268	    /// only matters for the absolute first run after deploy.
269	    /// </para>
270	    /// </summary>
271	    private async Task<InstructorPayrollResult> AggregateInstructorAsync(
272	        Staff staff, StaffRateRevision? rates, IReadOnlyList<CalendarSession> sessions)
273	    {
274	        // ── Snapshot the rate sheet onto the result up front ─────────────
275	        // Even if the calculation below short-circuits (e.g. zero sessions),
276	        // the snapshot makes the per-instructor row self-describing.
277	        var result = new InstructorPayrollResult
278	        {
279	            InstructorId = staff.Id!,
280	            InstructorNameSnapshot = staff.Name ?? string.Empty,
281	            RateRevisionId = rates?.Id,
282	            CommissionModelSnapshot = rates?.CommissionModel ?? staff.CommissionModel,
283	            BaseSalarySnapshot = rates?.BaseSalary ?? staff.BaseSalary,
284	            GroupFlatRatePerClassSnapshot = rates?.GroupFlatRatePerClass ?? staff.GroupFlatRatePerClass,
285	            GroupRatePerHeadSnapshot = rates?.GroupRatePerHead ?? staff.GroupRatePerHead,
286	            RatePerHeadSnapshot = rates?.RatePerHead ?? staff.RatePerHead,
287	            PrivateRatePerHeadSnapshot = rates?.PrivateRatePerHead ?? staff.PrivateRatePerHead,
288	            HasTieredPrivateCommissionSnapshot = rates?.HasTieredPrivateCommission ?? staff.HasTieredPrivateCommission,
289	            FlatPrivateCommissionPctSnapshot = rates?.FlatPrivateCommissionPct ?? staff.FlatPrivateCommissionPct,
290	            UseMarginalHeadcountTiersSnapshot = rates?.UseMarginalHeadcountTiers ?? staff.UseMarginalHeadcountTiers,
291	            TiersSnapshot = (rates?.Tiers ?? staff.Tiers).Select(t => new CommissionTier
292	            {
293	                MinClasses = t.MinClasses,
294	                MaxClasses = t.MaxClasses,
295	                CommissionPercentage = t.CommissionPercentage,
296	            }).ToList(),
297	            HeadcountTiersSnapshot = (rates?.HeadcountTiers ?? staff.HeadcountTiers).Select(h => new HeadcountPayoutTier
298	            {
299	                MinStudents = h.MinStudents,
300	                MaxStudents = h.MaxStudents,
301	                RatePerStudent = h.RatePerStudent,
302	            }).ToList(),
303	            PrivateHeadcountTiersSnapshot = (rates?.PrivateHeadcountTiers ?? staff.PrivateHeadcountTiers).Select(h => new HeadcountPayoutTier
304	            {
305	                MinStudents = h.MinStudents,
306	                MaxStudents = h.MaxStudents,
307	                RatePerStudent = h.RatePerStudent,
308	            }).ToList(),
309	
310	            BaseSalaryAmount = rates?.BaseSalary ?? staff.BaseSalary,
311	        };
312	
313	        // ── Aggregate session-level earnings ───────────────────────────
314	        // Private fractional revenue is summed *raw* here, then the commission
315	        // rate is applied below once we know the class count for tier resolution.
316	        //
317	        // For PERCENTAGE_TIERED group classes, we also accumulate raw group revenue
318	        // so the tiered commission can be applied at the end.
319	        decimal privateRawRevenue = 0;
320	        decimal groupRawRevenue = 0;
321	        int totalClassesWithAttendees = 0;
322	        // Historical spreadsheet imports carry the exact per-class commission on
323	        // each attendance (ImportedCommissionAmount) — the studio's real rates were
324	        // manually negotiated per month, so they can't be recomputed. We total
325	        // these verbatim and fold them in AFTER the tier logic (which would
326	        // otherwise overwrite PrivateClassEarnings for PERCENTAGE_TIERED).
327	        decimal importedGroupComm = 0;
328	        decimal importedPrivateComm = 0;
329	        // Per-session admin commission overrides. Like imported commissions these
330	        // are verbatim amounts folded in AFTER the tier math (below) so the
331	        // PERCENTAGE_TIERED pass can't overwrite them.
332	        decimal overrideGroupComm = 0;
333	        decimal overridePrivateComm = 0;
334	        foreach (var session in sessions)
335	        {
336	            // Load attendances that actually showed up (CHECKED_IN or ARRIVED)
337	            // — the frontend sets "ARRIVED" via the status dropdown, but some
338	            // legacy code paths set "CHECKED_IN" directly. Accept both.
339	            var rawArrivedAttendances = await _attendances
340	                .Find(a => a.CalendarSessionId == session.Id
341	                        && (a.Status == "CHECKED_IN" || a.Status == "ARRIVED")
342	                        && a.Status != "CANCELLED")
343	                .ToListAsync();
344	
345	            // SPM-113 — money: an arrival only counts toward the instructor's
346	            // commission if the attendee both arrived AND paid. The owner
347	            // decision is to apply the paid rule EVERYWHERE — earnings total,
348	            // head-count payout, and tier thresholds — so we filter the arrived
349	            // set here, BEFORE it feeds any of those calculations. Genuinely
350	            // unpaid monetary arrivals count nowhere; PACKAGE_CREDIT and free
351	            // classes remain satisfied (see IsAttendancePaidAsync). The filter
352	            // is a pure read, so re-runs stay idempotent.
353	            var arrivedAttendances = new List<Attendance>();
354	            foreach (var a in rawArrivedAttendances)
355	            {
356	                if (await IsAttendancePaidAsync(a)) arrivedAttendances.Add(a);
357	            }
358	
359	            // Only count towards tiers if at least one paid attendee arrived.
360	            // Empty classes (or classes with only unpaid arrivals) must not
361	            // inflate the tier counter or generate any payout.
362	            if (arrivedAttendances.Count == 0) continue;
363	
364	            var isPrivateFmt = session.Capacity == 1 || session.Format == "PRIVATE" || session.Format == "DUO";
365	
366	            // ── Per-session admin commission override short-circuit ──
367	            // An admin pinned this session's instructor commission to an exact
368	            // amount on the class-detail panel, replacing the normal rate/tier
369	            // computation for this ONE session's instructor. We only reach here
370	            // once the class actually ran — the `arrivedAttendances.Count == 0`
371	            // guard above already rejected empty / no-show classes — so the
372	            // override is never paid for a class nobody attended. Like the imported
373	            // short-circuit, the amount is folded in AFTER the tier math (see the
374	            // fold-in below) so PERCENTAGE_TIERED can't overwrite it. Non-negativity
375	            // is enforced at the API; clamp defensively.
376	            if (session.CommissionOverride is { } overrideAmount)
377	            {
378	                var amount = Math.Max(0m, overrideAmount);
379	                totalClassesWithAttendees++;
380	                if (isPrivateFmt) { result.TotalPrivateClasses++; overridePrivateComm += amount; }
381	                else { result.TotalGroupClasses++; overrideGroupComm += amount; }
382	                continue;
383	            }
384	
385	            // ── Imported historical commission short-circuit ──
386	            // If any attendee in this session carries a spreadsheet-imported
387	            // commission, use those amounts verbatim and skip the recompute for
388	            // this whole session (imported sessions are all-or-nothing).
389	            // Sum every imported commission on the session — the spreadsheet's
390	            // amount is authoritative even for rows flagged "doesn't count as a
391	            // class" (they still carried a recorded commission in the P&L).
392	            var importedForSession = arrivedAttendances
393	                .Where(a => a.ImportedCommissionAmount.HasValue)
394	                .Sum(a => a.ImportedCommissionAmount!.Value);
395	            if (arrivedAttendances.Any(a => a.ImportedCommissionAmount.HasValue))
396	            {
397	                totalClassesWithAttendees++;
398	                if (isPrivateFmt) { result.TotalPrivateClasses++; importedPrivateComm += importedForSession; }
399	                else { result.TotalGroupClasses++; importedGroupComm += importedForSession; }
400	                continue;
401	            }
402	
403	            var isPrivate = session.Capacity == 1 || session.Format == "PRIVATE";
404	            if (!isPrivate)
405	            {
406	                result.TotalGroupClasses++;
407	                totalClassesWithAttendees++;
408	
409	                if (result.CommissionModelSnapshot == "FIXED_HEADCOUNT")
410	                {
411	                    // SPM-90 — the headcount ladder is per SEAT, not per attendance
412	                    // ROW. A group booking of N seats (att.Quantity == N) counts as
413	                    // N students, exactly like PERCENTAGE_TIERED sums per-attendee
414	                    // revenue with quantity. Empty-arrival attendees
415	                    // (CountsTowardsCommission == false) are excluded from the count.
416	                    var seatHeadcount = arrivedAttendances
417	                        .Where(a => a.CountsTowardsCommission)
418	                        .Sum(a => Math.Max(1, a.Quantity));
419	
420	                    result.GroupClassEarnings += ResolveHeadcountPayoutFromSnapshot(result, seatHeadcount);
421	                }
422	                else if (result.CommissionModelSnapshot == "PERCENTAGE_TIERED")
423	                {
424	                    // ── PERCENTAGE_TIERED for group classes ──────────────────
425	                    // The instructor earns a % of the revenue generated by the
426	                    // attendees who arrived. Revenue per attendee is determined
427	                    // from their linked invoice paid balance, falling back to
428	                    // the session's drop-in price.
429	                    foreach (var att in arrivedAttendances)
430	                    {
431	                        if (!att.CountsTowardsCommission) continue;
432	
433	                        var revenueBase = await ResolveAttendeeRevenueAsync(att, session);
434	
435	                        // Apply referral discount.
436	                        var discountPct = att.ReferralDiscountPct.HasValue
437	                            ? Math.Clamp(att.ReferralDiscountPct.Value, 0m, 1m)
438	                            : 0m;
439	                        var seatRev = revenueBase * (1m - discountPct);
440	                        // Net any booking-page promo discount (e.g. bring-a-friend free seat).
441	                        if (att.PromoDiscountAmount is > 0m)
442	                            seatRev = Math.Max(0m, seatRev - att.PromoDiscountAmount.Value);
443	                        groupRawRevenue += seatRev;
444	                    }
445	
446	                    // Also add flat rate + per-head if configured (hybrid model).
447	                    result.GroupClassEarnings += result.GroupFlatRatePerClassSnapshot;
448	                    result.GroupClassEarnings += result.GroupRatePerHeadSnapshot * arrivedAttendances.Count;
449	                }
450	                else
451	                {
452	                    // Default flat-rate model.
453	                    result.GroupClassEarnings += result.GroupFlatRatePerClassSnapshot;
454	                    result.GroupClassEarnings += result.GroupRatePerHeadSnapshot * arrivedAttendances.Count;
455	                }
456	            }
457	            else
458	            {
459	                result.TotalPrivateClasses++;
460	                totalClassesWithAttendees++;
461	
462	                if (result.CommissionModelSnapshot == "FIXED_HEADCOUNT")
463	                {
464	                    var seatHeadcount = arrivedAttendances
465	                        .Where(a => a.CountsTowardsCommission)
466	                        .Sum(a => Math.Max(1, a.Quantity));
467	
468	                    result.PrivateClassEarnings += ResolveHeadcountPayoutFromSnapshot(result, seatHeadcount, isPrivate: true);
469	                }
470	                else
471	                {
472	                    foreach (var att in arrivedAttendances)
473	                    {
474	                        if (!att.CountsTowardsCommission) continue;
475	
476	                        var revenueBase = await ResolveAttendeeRevenueAsync(att, session);
477	
478	                        // Apply referral discount.
479	                        var discountPct = att.ReferralDiscountPct.HasValue
480	                            ? Math.Clamp(att.ReferralDiscountPct.Value, 0m, 1m)
481	                            : 0m;
482	                        var seatRev = revenueBase * (1m - discountPct);
483	                        if (att.PromoDiscountAmount is > 0m)
484	                            seatRev = Math.Max(0m, seatRev - att.PromoDiscountAmount.Value);
485	                        privateRawRevenue += seatRev;
486	                    }
487	                }
488	            }
489	        }
490	
491	        // ── Apply tiered commission rates ──────────────────────────────
492	        // For PERCENTAGE_TIERED, the tier is resolved using the TOTAL class
493	        // count (group + private) that had at least one arrived attendee.
494	        // The same rate applies to both group and private raw revenue.
495	        if (result.CommissionModelSnapshot == "PERCENTAGE_TIERED")
496	        {
497	            var totalCountForTier = totalClassesWithAttendees;
498	            var tieredRate = ResolvePrivateCommissionRateFromSnapshot(result, totalCountForTier);
499	            result.PrivateClassEarnings = privateRawRevenue * tieredRate;
500	            result.GroupClassEarnings += groupRawRevenue * tieredRate;
501	        }
502	        else if (result.CommissionModelSnapshot != "FIXED_HEADCOUNT")
503	        {
504	            // Non-tiered flat model: apply the flat private commission rate to the
505	            // raw revenue accumulated in the loop.
506	            //
507	            // FIXED_HEADCOUNT MUST be excluded here. Its private earnings are already
508	            // final — computed per-session from the headcount tiers inside the loop
509	            // (see ResolveHeadcountPayoutFromSnapshot above). This branch would
510	            // otherwise overwrite that with `privateRawRevenue * privateRate`, and
511	            // privateRawRevenue is only ever accumulated on the percentage path, so
512	            // for a headcount instructor it is 0 — zeroing out every private-class
513	            // commission (the Linna bug).
514	            var privateRate = ResolvePrivateCommissionRateFromSnapshot(result, result.TotalPrivateClasses);
515	            result.PrivateClassEarnings = privateRawRevenue * privateRate;
516	        }
517	
518	        // Fold in the verbatim spreadsheet-imported commissions AFTER the tier
519	        // logic (which overwrites PrivateClassEarnings for PERCENTAGE_TIERED).
520	        result.GroupClassEarnings += importedGroupComm + overrideGroupComm;
521	        result.PrivateClassEarnings += importedPrivateComm + overridePrivateComm;
522	
523	        result.TotalPay = result.BaseSalaryAmount + result.GroupClassEarnings + result.PrivateClassEarnings;
524	        return result;
525	    }
