527	    /// <inheritdoc />
528	    public async Task<decimal> CalculateTotalCommissionsAsync(DateTime start, DateTime end)
529	    {
530	        // Mirror CalculatePayrollAsync's session scope, but don't persist a run.
531	        var sessions = await _sessions
532	            .Find(s => s.StartTime >= start && s.StartTime <= end
533	                    && s.Status == "COMPLETED"
534	                    && s.Origin != "BLOCK")
535	            .ToListAsync();
536	
537	        decimal total = 0m;
538	        foreach (var group in sessions.GroupBy(s => s.InstructorId))
539	        {
540	            var instructorId = group.Key;
541	            if (string.IsNullOrEmpty(instructorId)) continue;
542	
543	            var staff = await _staff.Find(s => s.Id == instructorId).FirstOrDefaultAsync();
544	            if (staff is null) continue;
545	
546	            var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);
547	            revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);
548	
549	            var result = await AggregateInstructorAsync(staff, revision, group.ToList());
550	            total += result.GroupClassEarnings + result.PrivateClassEarnings;
551	        }
552	        return total;
553	    }
