555	    /// <summary>
556	    /// Checks whether a <see cref="MonthlyCommissionOverride"/> exists for the
557	    /// given staff member in the calendar month containing <paramref name="periodEnd"/>.
558	    /// If one is found, its fields are merged into a copy of <paramref name="baseRevision"/>
559	    /// (or a fresh synthetic revision if none exists) so the downstream
560	    /// <see cref="AggregateInstructorAsync"/> never needs to know the difference.
561	    /// </summary>
562	    private async Task<StaffRateRevision?> ApplyCommissionOverrideAsync(
563	        string staffId, DateTime periodEnd, StaffRateRevision? baseRevision)
564	    {
565	        var year = periodEnd.Year;
566	        var month = periodEnd.Month;
567	
568	        var ovr = await _commissionOverrides
569	            .Find(o => o.StaffId == staffId && o.Year == year && o.Month == month)
570	            .FirstOrDefaultAsync();
571	
572	        if (ovr is null) return baseRevision;
573	
574	        // Build a synthetic revision that inherits non-commission fields from
575	        // the base revision (so BaseSalary, headcount rates, etc. are still
576	        // version-controlled by the revision ledger) and overrides only the
577	        // commission-specific fields.
578	        var merged = baseRevision is not null
579	            ? new StaffRateRevision
580	            {
581	                Id = baseRevision.Id,
582	                StaffId = baseRevision.StaffId,
583	                StaffNameSnapshot = baseRevision.StaffNameSnapshot,
584	                EffectiveFrom = baseRevision.EffectiveFrom,
585	                ChangeNote = $"[Override applied for {year}-{month:D2}] " + baseRevision.ChangeNote,
586	                IsBootstrap = baseRevision.IsBootstrap,
587	
588	                // Commission fields — from the override.
589	                CommissionModel = ovr.CommissionModel,
590	                Tiers = ovr.Tiers.Select(t => new CommissionTier
591	                {
592	                    MinClasses = t.MinClasses,
593	                    MaxClasses = t.MaxClasses,
594	                    CommissionPercentage = t.CommissionPercentage,
595	                }).ToList(),
596	                HasTieredPrivateCommission = ovr.HasTieredPrivateCommission,
597	                FlatPrivateCommissionPct = ovr.FlatPrivateCommissionPct,
598	                GroupFlatRatePerClass = ovr.GroupFlatRatePerClass,
599	                GroupRatePerHead = ovr.GroupRatePerHead,
600	                FreeGroupClassRate = ovr.FreeGroupClassRate,
601	                FreePrivateClassRate = ovr.FreePrivateClassRate,
602	                RatePerHead = ovr.RatePerHead,
603	                HeadcountTiers = ovr.HeadcountTiers.Select(h => new HeadcountPayoutTier
604	                {
605	                    MinStudents = h.MinStudents,
606	                    MaxStudents = h.MaxStudents,
607	                    RatePerStudent = h.RatePerStudent,
608	                }).ToList(),
609	                PrivateRatePerHead = ovr.PrivateRatePerHead,
610	                PrivateHeadcountTiers = ovr.PrivateHeadcountTiers.Select(h => new HeadcountPayoutTier
611	                {
612	                    MinStudents = h.MinStudents,
613	                    MaxStudents = h.MaxStudents,
614	                    RatePerStudent = h.RatePerStudent,
615	                }).ToList(),
616	                UseMarginalHeadcountTiers = ovr.UseMarginalHeadcountTiers,
617	
618	                // Non-commission fields — from the base revision.
619	                BaseSalary = baseRevision.BaseSalary,
620	                BaseRate = baseRevision.BaseRate,
621	            }
622	            : new StaffRateRevision
623	            {
624	                StaffId = staffId,
625	                EffectiveFrom = periodEnd,
626	                ChangeNote = $"[Synthetic from override for {year}-{month:D2}]",
627	
628	                CommissionModel = ovr.CommissionModel,
629	                Tiers = ovr.Tiers.Select(t => new CommissionTier
630	                {
631	                    MinClasses = t.MinClasses,
632	                    MaxClasses = t.MaxClasses,
633	                    CommissionPercentage = t.CommissionPercentage,
634	                }).ToList(),
635	                HasTieredPrivateCommission = ovr.HasTieredPrivateCommission,
636	                FlatPrivateCommissionPct = ovr.FlatPrivateCommissionPct,
637	                GroupFlatRatePerClass = ovr.GroupFlatRatePerClass,
638	                GroupRatePerHead = ovr.GroupRatePerHead,
639	                FreeGroupClassRate = ovr.FreeGroupClassRate,
640	                FreePrivateClassRate = ovr.FreePrivateClassRate,
641	                RatePerHead = ovr.RatePerHead,
642	                HeadcountTiers = ovr.HeadcountTiers.Select(h => new HeadcountPayoutTier
643	                {
644	                    MinStudents = h.MinStudents,
645	                    MaxStudents = h.MaxStudents,
646	                    RatePerStudent = h.RatePerStudent,
647	                }).ToList(),
648	                PrivateRatePerHead = ovr.PrivateRatePerHead,
649	                PrivateHeadcountTiers = ovr.PrivateHeadcountTiers.Select(h => new HeadcountPayoutTier
650	                {
651	                    MinStudents = h.MinStudents,
652	                    MaxStudents = h.MaxStudents,
653	                    RatePerStudent = h.RatePerStudent,
654	                }).ToList(),
655	                UseMarginalHeadcountTiers = ovr.UseMarginalHeadcountTiers,
656	                BaseSalary = ovr.BaseSalary,
657	                BaseRate = ovr.BaseRate,
658	            };
659	
660	        return merged;
661	    }
