663	    /// <summary>
664	    /// SPM-113 — money: decides whether an arrived attendee has actually PAID,
665	    /// and therefore whether they count toward the instructor's commission
666	    /// (earnings, head-count payout, and tier thresholds alike). Genuinely
667	    /// unpaid monetary arrivals are excluded everywhere.
668	    ///
669	    /// <para>Paid rules (owner decision):</para>
670	    /// <list type="bullet">
671	    ///   <item><c>PACKAGE_CREDIT</c> bookings are always paid (the credit was
672	    ///   purchased up front).</item>
673	    ///   <item>Free classes (<see cref="Attendance.IsFreeClass"/>) count as
674	    ///   satisfied — they are deliberately 0₫ revenue, NOT unpaid debt.</item>
675	    ///   <item>Monetary bookings are paid when a linked <see cref="Invoice"/>
676	    ///   has <c>Status == "PAID"</c>, OR <see cref="Attendance.AmountPaid"/>
677	    ///   is &gt; 0, OR <see cref="Attendance.AmountDueAtStudio"/> is null/0
678	    ///   (nothing left to collect at the studio).</item>
679	    /// </list>
680	    ///
681	    /// <para>The invoice lookup mirrors the one in
682	    /// <see cref="ResolveAttendeeRevenueAsync"/> so the two surfaces stay
683	    /// consistent. This is a pure read — re-runs remain idempotent.</para>
684	    /// </summary>
685	    private async Task<bool> IsAttendancePaidAsync(Attendance att)
686	    {
687	        // Package-credit redemptions were paid for when the package was bought.
688	        if (att.PaymentMethod == "PACKAGE_CREDIT") return true;
689	
690	        // Free classes are satisfied (0₫ by design, not an unpaid balance).
691	        if (att.IsFreeClass) return true;
692	
693	        // Direct evidence of payment on the attendance row.
694	        if ((att.AmountPaid ?? 0m) > 0m) return true;
695	
696	        // Nothing left to collect at the studio ⇒ treated as paid. (null is
697	        // treated as "no outstanding balance" — matches legacy rows that
698	        // pre-date the field and the fully-prepaid online flow.)
699	        if ((att.AmountDueAtStudio ?? 0m) <= 0m) return true;
700	
701	        // Otherwise, a linked PAID invoice settles it. Mirrors the invoice
702	        // lookup in ResolveAttendeeRevenueAsync.
703	        var linkedInvoice = await _invoices.Find(
704	            Builders<Invoice>.Filter.ElemMatch(
705	                i => i.Lines,
706	                Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, att.Id)
707	            )
708	        ).FirstOrDefaultAsync();
709	
710	        return linkedInvoice is not null && linkedInvoice.Status == "PAID";
711	    }
