713	    /// <summary>
714	    /// Resolves the revenue attributed to a single attendee for commission
715	    /// calculation. Uses the linked invoice's paid balance as the source of
716	    /// truth; falls back to the session's snapshotted DropInPrice when no
717	    /// invoice exists (e.g. package credit or pre-paid bookings).
718	    /// </summary>
719	    private async Task<decimal> ResolveAttendeeRevenueAsync(Attendance att, CalendarSession session)
720	    {
721	        var qty = Math.Max(1, att.Quantity);
722	
723	        // ── Package-credit bookings ──────────────────────────────────────
724	        // When a client redeems a pre-paid package, the invoice shows 0₫ (no new
725	        // money changed hands), but the instructor's commission must be based on
726	        // the class's value. Business rule (studio policy): the commission base is
727	        // the per-class rate WITHIN the package — i.e. what the package sold for
728	        // divided by its credits — NOT the full drop-in rate. That per-class value
729	        // is stored on the ClientPackage as FractionalValuePerClass.
730	        if (att.PaymentMethod == "PACKAGE_CREDIT")
731	        {
732	            if (!string.IsNullOrEmpty(att.PackageInstanceId))
733	            {
734	                var pkg = await _clientPackages
735	                    .Find(p => p.Id == att.PackageInstanceId)
736	                    .FirstOrDefaultAsync();
737	                if (pkg is not null && pkg.FractionalValuePerClass > 0m)
738	                    return pkg.FractionalValuePerClass * qty;
739	            }
740	            // Fallback only when the package's per-class value is unknown
741	            // (e.g. missing package link) — the session's drop-in price.
742	            return (session.DropInPrice ?? 0m) * qty;
743	        }
744	
745	        // ── Monetary-payment bookings ────────────────────────────────────
746	        // 1. Try to find a linked invoice for this attendance and use its
747	        //    actual paid amount (TotalNet) as the revenue base.
748	        var linkedInvoice = await _invoices.Find(
749	            Builders<Invoice>.Filter.ElemMatch(
750	                i => i.Lines,
751	                Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, att.Id)
752	            )
753	        ).FirstOrDefaultAsync();
754	
755	        // The "VAT (online only)" surcharge is a pass-through fee, NOT studio
756	        // revenue, so it must never be part of the commission base. It is stored
757	        // separately as Invoice.OnlineFeeAmount (never inside a line), so the
758	        // per-line total below is already fee-free; only the whole-invoice and
759	        // AmountPaid fallbacks need the fee stripped out. Apportion the fee to
760	        // this attendee by their share of the invoice's line subtotal.
761	        decimal onlineFeeShare = 0m;
762	        if (linkedInvoice is not null && linkedInvoice.OnlineFeeAmount > 0m)
763	        {
764	            var lineSubtotal = linkedInvoice.Lines.Sum(l => l.UnitPrice * l.Quantity - l.LineDiscount);
765	            var myLine = linkedInvoice.Lines.FirstOrDefault(l => l.AttendanceId == att.Id);
766	            var myLineTotal = myLine is not null ? (myLine.UnitPrice * myLine.Quantity - myLine.LineDiscount) : 0m;
767	            onlineFeeShare = (lineSubtotal > 0m && myLineTotal > 0m)
768	                ? linkedInvoice.OnlineFeeAmount * (myLineTotal / lineSubtotal)
769	                : linkedInvoice.OnlineFeeAmount; // single-booking invoice: exclude the whole fee
770	        }
771	
772	        if (linkedInvoice is not null && linkedInvoice.Status == "PAID")
773	        {
774	            // Prefer the specific line total (already excludes the online fee).
775	            // Note: invoice line already includes quantity in its total.
776	            var line = linkedInvoice.Lines
777	                .FirstOrDefault(l => l.AttendanceId == att.Id);
778	            if (line is not null)
779	            {
780	                var lineTotal = line.UnitPrice * line.Quantity - line.LineDiscount;
781	                if (lineTotal > 0m) return lineTotal;
782	            }
783	            // Whole-invoice fallback: strip the online fee out of the net.
784	            var netExFee = linkedInvoice.TotalNet - linkedInvoice.OnlineFeeAmount;
785	            if (netExFee > 0m) return netExFee;
786	        }
787	
788	        // 2. If the attendance has a recorded paid amount, use that — less this
789	        //    attendee's share of any online fee that was bundled into the payment.
790	        if ((att.AmountPaid ?? 0m) > 0m)
791	        {
792	            return Math.Max(0m, (att.AmountPaid ?? 0m) - onlineFeeShare);
793	        }
794	
795	        // 3. No monetary payment recorded (e.g. booked "pay at studio" but the
796	        //    client is a package member). Business rule: if the client holds an
797	        //    active package for THIS class format, the class draws from that
798	        //    package — commission on the package's per-class rate, NOT the full
799	        //    drop-in. Only genuine full-price drop-in payments (captured in steps
800	        //    1–2 above) commission on the drop-in rate.
801	        if (!string.IsNullOrEmpty(session.Format))
802	        {
803	            var memberPkg = await _clientPackages
804	                .Find(p => p.ClientId == att.ClientId
805	                           && p.Format == session.Format
806	                           && p.FractionalValuePerClass > 0m
807	                           && (p.Status == "ACTIVE" || p.Status == "LOW_BALANCE"))
808	                .FirstOrDefaultAsync();
809	            if (memberPkg is not null)
810	                return memberPkg.FractionalValuePerClass * qty;
811	        }
812	
813	        // 4. Fallback: session's snapshotted drop-in price × quantity.
814	        return (session.DropInPrice ?? 0m) * qty;
815	    }
