817	    /// <summary>
818	    /// Looks up the commission rate that applies to the given private-class count
819	    /// for this staff member, reading from the live <see cref="Staff"/> document.
820	    ///
821	    /// <para>
822	    /// Preserved for backward compatibility with the test suite + the instructor
823	    /// self-service portal's tier-progress meter (which reads the LIVE rate
824	    /// sheet to compute "X more classes until your next tier" — that's a
825	    /// forecast, not a historical fact, so the live sheet is correct here).
826	    /// </para>
827	    ///
828	    /// <para>
829	    /// The payroll calculation itself goes through
830	    /// <see cref="ResolvePrivateCommissionRateFromSnapshot"/> instead, so it
831	    /// is unaffected by future edits to <c>Staff</c>.
832	    /// </para>
833	    /// </summary>
834	    public static decimal ResolvePrivateCommissionRate(Staff staff, int privateClassCount)
835	    {
836	        if (!staff.HasTieredPrivateCommission || staff.Tiers.Count == 0)
837	        {
838	            return NormalizeCommissionPct(staff.FlatPrivateCommissionPct);
839	        }
840	        var matching = staff.Tiers
841	            .Where(t => privateClassCount >= t.MinClasses
842	                     && (!t.MaxClasses.HasValue || privateClassCount <= t.MaxClasses.Value))
843	            .OrderByDescending(t => t.CommissionPercentage)
844	            .FirstOrDefault();
845	        return NormalizeCommissionPct(matching?.CommissionPercentage ?? staff.FlatPrivateCommissionPct);
846	    }
847	
848	    /// <summary>
849	    /// Snapshot-driven counterpart of <see cref="ResolvePrivateCommissionRate"/>.
850	    /// Reads only from the <see cref="InstructorPayrollResult"/> snapshot block
851	    /// so historical re-runs are guaranteed to reproduce the original rate even
852	    /// after the live <see cref="Staff"/> document has been edited.
853	    /// </summary>
854	    private static decimal ResolvePrivateCommissionRateFromSnapshot(InstructorPayrollResult r, int privateClassCount)
855	    {
856	        if (!r.HasTieredPrivateCommissionSnapshot || r.TiersSnapshot.Count == 0)
857	        {
858	            return NormalizeCommissionPct(r.FlatPrivateCommissionPctSnapshot);
859	        }
860	        var matching = r.TiersSnapshot
861	            .Where(t => privateClassCount >= t.MinClasses
862	                     && (!t.MaxClasses.HasValue || privateClassCount <= t.MaxClasses.Value))
863	            .OrderByDescending(t => t.CommissionPercentage)
864	            .FirstOrDefault();
865	        return NormalizeCommissionPct(matching?.CommissionPercentage ?? r.FlatPrivateCommissionPctSnapshot);
866	    }
